from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
CLUE_FILE = next(ROOT.joinpath("clues").rglob("high_school_electromagnetism_terms.json"))


EXPLANATIONS = {
    "电荷": r"""电荷是物体参与电相互作用时表现出的基本属性，通常分为正电荷和负电荷。同种电荷相互排斥，异种电荷相互吸引，说明电荷的符号会决定相互作用方向。电荷量常用 $q$ 表示，单位是库仑；宏观物体所带电荷总是元电荷 $e$ 的整数倍，可写为 $q=ne$，其中 $n$ 是整数。电荷还是守恒量，孤立系统中的电荷代数和不会凭空增加或减少。理解电荷后，电场、电势和电路中的电流都可以看作它在不同条件下的表现。""",
    "正电荷": r"""正电荷是电荷的两种符号之一，约定质子所带电荷为正。带正电的物体会排斥其他正电荷，吸引负电荷，这种方向差别是判断静电现象的基础。若某物体所带电荷量为 $q>0$，就称它带正电；在电场中受力满足 $\mathbf F=q\mathbf E$，其中 $\mathbf E$ 为电场强度。因为 $q$ 为正，受力方向与电场方向相同，所以电场线的方向也常定义为正试探电荷所受电场力方向。这个约定把抽象的电场方向和可观察的受力方向联系起来。""",
    "负电荷": r"""负电荷是与正电荷相对的电荷符号，电子所带电荷就是负电荷。带负电的物体会排斥其他负电荷，吸引正电荷。若电荷量写作 $q<0$，它在电场中的受力仍满足 $\mathbf F=q\mathbf E$，但由于 $q$ 为负，力的方向与电场方向相反。摩擦起电、感应起电和电路导电中，实际移动得最活跃的常常是电子，因此负电荷的转移会决定物体显正电还是显负电。理解负号的物理意义，可以避免把电场方向和电子运动方向简单混同。""",
    "元电荷": r"""元电荷是自然界中最小的自由电荷量单位，通常记为 $e$。质子带电量为 $+e$，电子带电量为 $-e$，其数值约为 $e=1.60\times10^{-19}\,\mathrm C$。宏观物体带电量满足 $q=ne$，其中 $n$ 为整数，这叫电荷量子化。高中阶段不需要深入粒子结构，但这个关系说明电荷不是连续任意取值的。许多静电题会给出若干电子得失数，正是用 $q=ne$ 把微观粒子数和宏观电荷量连接起来。它也是理解电流、电解和基本粒子电性的重要起点。""",
    "电荷量": r"""电荷量表示物体所带电荷的多少，常用 $q$ 或 $Q$ 表示，单位是库仑。它既有大小也有正负号，正负号反映电荷类型，大小反映相互作用强弱。若物体得失了 $n$ 个电子，电荷量的大小可写为 $|q|=ne$，其中 $e$ 是元电荷。库仑定律中 $F=k|q_1q_2|/r^2$ 说明，两个带电体之间的静电力与电荷量乘积成正比。电路中电流也由电荷量转移来定义，$I=\Delta q/\Delta t$ 表示单位时间通过导体横截面的电荷量。""",
    "电荷守恒定律": r"""电荷守恒定律说明，在孤立系统中电荷的代数总量保持不变。摩擦起电、接触起电或感应起电都不是创造电荷，而是正负电荷在物体之间或物体内部重新分布。若系统初末状态的总电荷分别为 $Q_i$ 和 $Q_f$，则有 $Q_i=Q_f$。这里的总电荷要带符号相加，正负电荷可以相互抵消。这个定律常用于判断两个物体接触后带电量如何分配，也用于分析验电器张角变化。它把复杂的起电现象收束为一个可靠的总量约束。""",
    "静电现象": r"""静电现象是电荷相对静止或缓慢分布时产生的吸引、排斥和放电等现象。摩擦过的塑料棒能吸引小纸屑，干燥天气衣物容易贴身，都是电荷分布改变后的结果。静电力可用库仑定律估计，$F=k|q_1q_2|/r^2$，其中 $q_1,q_2$ 是两物体所带电荷量，$r$ 是距离。静电现象不一定要求物体净带电，感应时电荷重新分布也能产生吸引。学习静电现象的重点，是分清电荷转移、极化分布和实际受力三件事。""",
    "摩擦起电": r"""摩擦起电是两个不同材料相互摩擦后带上等量异种电荷的现象。摩擦并不创造电荷，而是电子从一个物体转移到另一个物体，使失去电子的一方带正电，得到电子的一方带负电。若转移电子数为 $n$，两物体电荷量大小均为 $q=ne$。这个关系体现电荷守恒：两物体组成的系统总电荷仍为零。摩擦起电常在绝缘体上更明显，因为电荷不易迅速流走。它解释了塑料梳吸引纸屑、气球吸附墙面等现象，也是认识电荷转移的直观入口。""",
    "感应起电": r"""感应起电是带电体靠近导体时，不直接接触也能使导体内部电荷重新分布，并在接地或分离后留下净电荷的过程。靠近的外电荷产生电场，使导体中的自由电子移动，近端和远端出现异号分布。静电平衡时导体内部电场为零，可理解为外电场与感生电荷产生的电场相互抵消，即 $\mathbf E_{\rm in}=0$。若此时接地，电子可流入或流出导体，断开接地后再移走带电体，导体就带上电荷。感应起电强调的是电荷分布改变，而不是摩擦转移。""",
    "验电器": r"""验电器是用来检验物体是否带电以及粗略比较带电多少的仪器。常见金箔验电器中，带电体接触或靠近金属球后，电荷传到金箔或使其重新分布，两片金箔因带同种电荷而张开。张角大小与静电排斥力有关，而排斥力可由 $F=kq_1q_2/r^2$ 定性理解，其中 $q_1,q_2$ 是两片金箔上的电荷量。验电器不能直接给出精确电荷量，但能显示带电状态和电荷变化趋势。它在静电实验中常用于验证接触起电、感应起电和电荷守恒。""",
    "库仑定律": r"""库仑定律描述两个静止点电荷之间的相互作用力。若电荷量为 $q_1,q_2$，距离为 $r$，力的大小为 $F=k|q_1q_2|/r^2$，其中 $k$ 是静电力常量。力沿两电荷连线方向，同号相斥、异号相吸。这个平方反比关系说明距离增大时静电力迅速减小。库仑定律适用于点电荷或可近似看成点电荷的带电体，是电场强度、电势能和许多静电平衡问题的基础。多个电荷同时存在时，实际电场和受力可由各作用的矢量叠加得到。""",
    "电场": r"""电场是带电体周围存在的一种物理场，用来描述电荷对其他电荷施加作用的能力。把试探电荷放入某点，如果它受到电场力，就说该点存在电场。电场强度定义为 $\mathbf E=\mathbf F/q$，其中 $\mathbf F$ 是正试探电荷受到的力，$q$ 是试探电荷量。电场不是为了计算方便虚构出的箭头，而是能传递相互作用的物理对象。通过电场，可以把“两个电荷直接作用”的问题改写成“源电荷产生场，试探电荷受场作用”，这使复杂电荷分布的分析更清楚。""",
    "电场强度": r"""电场强度表示电场在某点的强弱和方向，定义为正试探电荷在该点所受电场力与电荷量之比：$\mathbf E=\mathbf F/q$。其中 $q$ 要足够小，以免明显改变原来的电场。电场强度是矢量，方向规定为正电荷受力方向。点电荷 $Q$ 在距离 $r$ 处产生的场强大小为 $E=k|Q|/r^2$，方向沿径向。这个量把不同试探电荷的受力统一起来：同一点的 $\mathbf E$ 由源电荷决定，而实际受力再由 $\mathbf F=q\mathbf E$ 给出。""",
    "电场线": r"""电场线是形象表示电场分布的曲线。曲线上某点的切线方向表示电场强度方向，线越密的地方电场越强。电场线从正电荷出发，终止于负电荷或无穷远，这与正试探电荷的受力方向一致。若用 $\mathbf E$ 表示电场强度，电场线方向就是 $\mathbf E$ 的方向；但电场线本身不是实际存在的细线。电场线不能相交，因为同一点的电场方向只能有一个。通过电场线可以快速判断带电体周围受力方向、场强大小变化以及等势面的垂直关系。""",
    "匀强电场": r"""匀强电场是在各点电场强度大小和方向都相同的电场，常用平行且等间距的电场线表示。平行板电容器中间区域常近似看作匀强电场。若两板间电势差为 $U$、距离为 $d$，场强大小可写为 $E=U/d$。这里 $U$ 表示电压，$d$ 表示沿电场方向的距离。带电粒子在匀强电场中受恒力 $\mathbf F=q\mathbf E$，因此会产生类似匀加速运动的效果。匀强电场把空间变化暂时简化掉，便于研究电势差、做功和带电粒子偏转。""",
    "电势能": r"""电势能是电荷在电场中由于位置而具有的能量，可以类比重力势能。选定参考点后，把电荷从参考点缓慢移到某点，外力所做的功就对应电荷和电场共同具有的电势能。若该点电势为 $\varphi$，电荷量为 $q$，则 $E_p=q\varphi$。这里 $\varphi$ 由电场和参考点决定，$q$ 决定同一点处具体电荷的能量大小。电场力做正功时电势能减少，做负功时电势能增加。静电场中电势能变化只与起止位置有关，与路径无关。""",
    "电势": r"""电势描述电场中某点的能量位置，是单位正电荷在该点具有的电势能。定义式为 $\varphi=E_p/q$，其中 $E_p$ 是电势能，$q$ 是放在该点的试探电荷量。电势是标量，不表示方向，但它的高低能决定电场力做功趋势。正电荷通常从高电势向低电势运动时电势能减少。两点间电势差 $U_{AB}=\varphi_A-\varphi_B$ 比单点电势更容易测量，因为单点电势依赖参考点。电势把电场中的能量问题转化为“每单位电荷能量”的比较。""",
    "电势差": r"""电势差表示电场中两点电势的差，也常称电压。若两点为 A、B，则 $U_{AB}=\varphi_A-\varphi_B$。电场力把电荷 $q$ 从 A 移到 B 所做的功满足 $W_{AB}=qU_{AB}$，这里的符号取决于移动方向和电荷正负。电势差比单点电势更重要，因为它直接对应能量变化并能被电压表测量。在匀强电场中，若沿电场方向距离为 $d$，有 $U=Ed$。这个关系连接了空间中的场强和电路中常见的电压读数。""",
    "电压": r"""电压是电势差在电路和实验测量中的常用名称，表示单位电荷通过两点时电场力能够提供或消耗的能量。定义可写为 $U=W/q$，其中 $W$ 是电场力或电源相关作用对电荷做的功，$q$ 是通过的电荷量。单位是伏特，$1\,\mathrm V=1\,\mathrm J/\mathrm C$。电压不是电流本身，而是推动电荷定向移动的能量差条件。电池两端有电压，导体两端接上电压后才可能形成持续电流。分析电路时，电压常与电流、电阻通过欧姆定律 $U=IR$ 联系起来。""",
    "等势面": r"""等势面是电势相同的点组成的面，在二维图中常画成等势线。电荷沿等势面移动时，电势差为零，因此电场力做功 $W=q\Delta\varphi=0$。等势面总与电场线垂直，因为若沿等势面方向存在电场分量，电荷移动就会发生电势变化。匀强电场中的等势面是与电场线垂直的一组平行平面；点电荷周围的等势面是同心球面。等势面让电势分布可视化，特别适合判断电场方向、比较电势高低以及分析导体静电平衡。""",
    "电容": r"""电容表示导体或电容器储存电荷的能力，定义为 $C=Q/U$。其中 $Q$ 是一个极板所带电荷量的大小，$U$ 是两极板间电势差。单位是法拉。电容大，并不表示一定已经带很多电，而是表示在同样电压下能储存更多电荷。平行板电容器的电容近似为 $C=\varepsilon S/d$，其中 $S$ 是极板正对面积，$d$ 是板间距离，$\varepsilon$ 与介质有关。这个公式说明结构和介质会决定储电能力。电容概念常用于充放电、滤波和电场能量问题。""",
    "电容器": r"""电容器是用来储存电荷和电场能量的元件，最简单形式是两块彼此绝缘、相互靠近的导体。接上电源后，两极板分别带等量异种电荷，板间形成电场。它的基本关系为 $Q=CU$，其中 $C$ 为电容，$U$ 为两极板间电压。储存在电容器中的能量可写为 $E=\frac12 CU^2$，表示充电过程中外界做功转化为电场能。电容器不让稳定直流电流穿过绝缘层，但在充放电过程中会有电荷在外电路移动。它是电路暂态和电场能量的核心模型。""",
    "平行板电容器": r"""平行板电容器由两块面积较大、相距较近的平行导体板组成，中间夹空气或介质。忽略边缘效应时，板间电场近似匀强，电容为 $C=\varepsilon S/d$。其中 $S$ 是正对面积，$d$ 是板间距离，$\varepsilon$ 是介质的电容率。这个公式说明增大面积、减小间距或加入电容率较大的介质，都能增大电容。若两板电压为 $U$，板间场强约为 $E=U/d$。平行板电容器把几何结构、电场和电路量联系得很直接，是高中电容题最常用的理想模型。""",
    "电流": r"""电流表示电荷的定向移动强弱，定义为单位时间通过导体横截面的电荷量：$I=\Delta q/\Delta t$。其中 $\Delta q$ 是时间 $\Delta t$ 内通过截面的电荷量，单位是安培。电流方向规定为正电荷定向移动方向，在金属导体中实际移动的电子方向与电流方向相反。电流不是单个电子的速度，而是大量电荷通过截面的总体效果。形成持续电流需要可移动电荷、闭合回路和维持电势差的电源。这个定义把微观电荷运动和电路表读数连接起来。""",
    "恒定电流": r"""恒定电流是大小和方向都不随时间改变的电流。对导体任一横截面，若相等时间内通过的电荷量相等，就有 $I=q/t$。这里 $q$ 是时间 $t$ 内通过截面的总电荷量。恒定电流要求电路处于稳定状态，导线中各处不持续积累电荷，否则电场分布会继续变化。普通直流电路在开关闭合并稳定后常可近似为恒定电流。学习恒定电流时，重点是用欧姆定律、串并联规律和能量关系分析电路，而不必追踪每个电子的瞬时运动。""",
    "电路": r"""电路是由电源、导线、用电器和开关等元件连接成的电流通路。只有形成闭合回路，电荷才能持续定向移动。电路中的基本量包括电流 $I$、电压 $U$ 和电阻 $R$，它们在许多元件上满足 $U=IR$。这里 $U$ 是元件两端电压，$I$ 是通过元件的电流。电源负责维持电势差，用电器把电能转化为其他形式的能量。画电路图时，导线通常看成等势连接，理想电流表电阻很小，理想电压表电阻很大。电路模型让真实装置被简化为可计算的连接关系。""",
    "电源": r"""电源是在电路中维持电势差并提供能量的装置，如干电池、蓄电池和发电机。电源内部依靠非静电力把电荷从低电势处移向高电势处，从而维持外电路中的电流。电源电动势定义为 $\mathcal E=W_{\rm non}/q$，其中 $W_{\rm non}$ 是非静电力移动电荷所做的功，$q$ 是电荷量。实际电源还常有内阻，闭合电路中端电压可写为 $U=\mathcal E-Ir$。电源不是“产生电荷”，而是把化学能、机械能等转化为电能并推动电荷循环。""",
    "电动势": r"""电动势描述电源把其他形式能量转化为电能的本领，常用 $\mathcal E$ 表示。定义式为 $\mathcal E=W_{\rm non}/q$，其中 $W_{\rm non}$ 是电源内部非静电力把电荷移过电源所做的功，$q$ 是通过电源的电荷量。单位也是伏特，但它不是普通电阻两端的电压。理想电源开路时端电压等于电动势；有电流时，若内阻为 $r$，端电压常为 $U=\mathcal E-Ir$。电动势帮助我们把电源内部的能量转换和外电路的电压分配区分开来。""",
    "内阻": r"""内阻是实际电源内部对电流的等效阻碍作用，常用 $r$ 表示。电源有电流通过时，内部也会消耗一部分能量并产生电压降。闭合电路中，若电动势为 $\mathcal E$、电流为 $I$，端电压可写为 $U=\mathcal E-Ir$。其中 $Ir$ 是内阻上的电压损失。内阻越大，同样电流下端电压下降越明显，电源发热也越多，内耗功率为 $P_{\rm in}=I^2r$。内阻概念解释了为什么电池接大电流负载时电压会降低，也让实际电源不同于理想电源。""",
    "外电路": r"""外电路是电源两极之外，由导线、开关和用电器构成的电流通路。电源在内部通过非静电力提升电荷能量，电荷进入外电路后在电场力作用下通过用电器，把电能转化为热、光或机械能。若外电路总电阻为 $R$，电源电动势为 $\mathcal E$、内阻为 $r$，闭合电路电流为 $I=\mathcal E/(R+r)$。外电路两端电压为 $U=IR$。分析闭合电路时，把外电路和电源内阻分开，可以清楚看出能量在用电器和电源内部的分配。""",
    "闭合电路": r"""闭合电路是电流能够持续流通的完整回路。只连接电源一端或开关断开时，电路不闭合，稳定电流不能形成。对含内阻电源和外电阻的简单闭合电路，电流满足 $I=\mathcal E/(R+r)$，其中 $\mathcal E$ 是电动势，$R$ 是外电路电阻，$r$ 是内阻。这个式子来自能量守恒：电源每单位电荷提供的能量，分配到外电路和内阻上。闭合电路还要满足电流连续性，串联部分电流相同。它是从零散元件走向完整电路分析的基本对象。""",
    "电阻": r"""电阻表示导体对电流的阻碍作用，常用 $R$ 表示，单位是欧姆。对于许多金属导体，在温度不变时电压和电流近似成正比，$R=U/I$。这里 $U$ 是导体两端电压，$I$ 是通过导体的电流。电阻越大，在相同电压下电流越小。均匀导体的电阻还满足 $R=\rho L/S$，其中 $\rho$ 是电阻率，$L$ 是长度，$S$ 是横截面积。电阻把材料、形状和电路行为联系起来，也是电能转化为内能的主要位置。""",
    "电阻率": r"""电阻率是反映材料本身导电性能的物理量，常用 $\rho$ 表示。对长度为 $L$、横截面积为 $S$ 的均匀导体，电阻满足 $R=\rho L/S$。这里 $R$ 还受几何尺寸影响，而 $\rho$ 主要由材料和温度决定。金属的电阻率通常较小，绝缘体的电阻率很大。温度变化会改变电阻率，因此精密电路和实验测量中常要说明温度条件。电阻率让我们能够比较不同材料的导电能力，而不是只比较某一段导线的电阻大小。""",
    "欧姆定律": r"""欧姆定律描述许多导体在温度等条件不变时，电流与两端电压成正比。常用形式是 $U=IR$，其中 $U$ 为电压，$I$ 为电流，$R$ 为电阻。也可写为 $I=U/R$，表示电压越大电流越大，电阻越大电流越小。欧姆定律适用于线性电阻元件，不适用于所有器件，例如二极管和灯丝在温度明显变化时就会偏离。它是直流电路计算的核心，把电路中的能量差、流动强度和阻碍作用压缩到一个简单关系里。""",
    "串联电路": r"""串联电路是元件首尾相接、只有一条电流路径的连接方式。由于电荷不能在中途积累，串联各处电流相同，$I_1=I_2=\cdots=I$。总电压等于各元件电压之和，$U=U_1+U_2+\cdots$。若各元件是电阻，则等效电阻为 $R=R_1+R_2+\cdots$。串联电路中电阻越大的元件分到的电压越大，因为 $U_i=IR_i$。这种连接常用于分压、限流和开关控制。分析串联电路时，先抓住“电流相同”，再用电压分配和功率关系即可。""",
    "并联电路": r"""并联电路是多个元件两端分别接在同一对节点上的连接方式。并联各支路电压相同，$U_1=U_2=\cdots=U$；总电流等于各支路电流之和，$I=I_1+I_2+\cdots$。对电阻并联，等效电阻满足 $1/R=1/R_1+1/R_2+\cdots$，因此并联后总电阻小于任一支路电阻。并联电路常用于家庭用电，因为各用电器能获得相同电压并相对独立工作。它的边界是共享同一对节点；只在局部相连而端点不同的元件不能简单看作并联。""",
    "滑动变阻器": r"""滑动变阻器是通过改变接入电路中电阻丝长度来调节电阻的元件。均匀电阻丝满足 $R=\rho L/S$，其中 $L$ 是接入长度，$S$ 是横截面积，$\rho$ 是电阻率。滑片移动时，$L$ 改变，电阻随之改变。它可以串联使用来调节电流，也可接成分压器来获得可变电压。实验中要注意接线柱选择，不同接法会导致电阻随滑片移动方向不同而增减。滑动变阻器让电路参数连续可调，因此常用于保护电路、控制灯泡亮度和测量伏安特性。""",
    "电功": r"""电功表示电流通过用电器时电场力或电源作用对电荷所做的功，也就是电能转化的量。若电压为 $U$，通过电荷量为 $q$，则 $W=Uq$。由于 $q=It$，也常写为 $W=UIt$，其中 $I$ 是电流，$t$ 是通电时间。对纯电阻元件，还可结合欧姆定律写成 $W=I^2Rt$ 或 $W=U^2t/R$。电功的单位是焦耳。它帮助我们计算电热、照明和电动机等用电过程中消耗或转化的能量。实际用电计量常以千瓦时记录一段时间的电功。""",
    "电功率": r"""电功率表示电能转化快慢，定义为单位时间内电流所做的功，$P=W/t$。在电路中常用 $P=UI$，其中 $U$ 是用电器两端电压，$I$ 是通过它的电流。对纯电阻，还可写为 $P=I^2R$ 或 $P=U^2/R$。单位是瓦特。电功率越大，同样时间内消耗或转化的电能越多。灯泡标有“220 V 40 W”，表示在额定电压下正常工作时功率为 40 W。电功率把电路状态和能量消耗联系起来，是判断发热、亮度和用电量的基本量。""",
    "焦耳定律": r"""焦耳定律描述电流通过导体时产生的热量。对电阻为 $R$ 的导体，通以电流 $I$、时间为 $t$，产生热量 $Q=I^2Rt$。这里的 $Q$ 是电能转化成的内能，单位是焦耳。若导体是纯电阻元件，电功全部转化为热，也可用 $Q=UIt$。焦耳定律解释了电炉、电热水壶和保险丝发热的原因，也提醒我们电路中过大电流会导致危险升温。公式中的平方关系说明，电流增大对发热影响特别明显，因此输电和用电安全都要控制电流。""",
    "磁场": r"""磁场是磁体、电流和运动电荷周围存在的物理场，能够对磁体或运动电荷施加磁力。磁场用磁感应强度 $\mathbf B$ 描述，其方向可由小磁针北极受力方向或右手定则判断。运动电荷在磁场中受洛伦兹力 $\mathbf F=q\mathbf v\times\mathbf B$，其中 $\mathbf v$ 是电荷速度。静止电荷不因磁场单独受力，这与电场不同。磁场概念把永磁体、通电导线和带电粒子运动统一起来，是理解安培力、电磁感应和电磁波的基础。""",
    "磁感线": r"""磁感线是用来形象表示磁场分布的曲线。曲线上某点的切线方向表示磁场方向，线越密处磁场越强。磁感线在磁体外部从北极出发指向南极，在磁体内部又从南极回到北极，因此总是闭合曲线。若用 $\mathbf B$ 表示磁感应强度，磁感线方向就是 $\mathbf B$ 的方向。磁感线不相交，因为同一点磁场方向唯一。它不是实际存在的线，而是帮助判断磁场方向和强弱的图示工具。和电场线相比，磁感线没有起点和终点，这是磁场的重要特征。""",
    "磁感应强度": r"""磁感应强度是描述磁场强弱和方向的矢量，常用 $\mathbf B$ 表示，单位是特斯拉。它可以通过磁场对运动电荷或通电导线的作用来定义。带电粒子在磁场中受力满足 $\mathbf F=q\mathbf v\times\mathbf B$，力的大小为 $F=qvB\sin\theta$，其中 $\theta$ 是速度与磁场方向夹角。通电直导线在匀强磁场中受安培力 $F=BIL\sin\theta$。这些关系说明，$\mathbf B$ 的方向和大小决定磁力效果，但磁力还依赖运动方向或电流方向。""",
    "匀强磁场": r"""匀强磁场是在空间各点磁感应强度大小和方向都相同的磁场，常用平行且等间距的磁感线表示。实验中蹄形磁铁两极间较小区域或长直螺线管内部可近似看作匀强磁场。若通电直导线长度为 $L$，电流为 $I$，与磁场夹角为 $\theta$，安培力大小为 $F=BIL\sin\theta$。在匀强磁场中，$B$ 不随位置变化，便于分析导线受力和带电粒子圆周运动。带电粒子垂直进入匀强磁场时，洛伦兹力提供向心力，有 $qvB=mv^2/r$。""",
    "安培力": r"""安培力是磁场对通电导线的作用力。导线中电流本质上是电荷定向移动，磁场对这些运动电荷施力，宏观上表现为导线受力。在匀强磁场中，长度为 $L$、电流为 $I$ 的直导线所受安培力大小为 $F=BIL\sin\theta$，其中 $B$ 是磁感应强度，$\theta$ 是电流方向与磁场方向夹角。力的方向可用左手定则判断。安培力是电动机工作的基础，也常用于判断通电导线在磁场中的运动趋势。公式中的 $\sin\theta$ 表明，电流平行磁场时不受安培力。""",
    "洛伦兹力": r"""洛伦兹力是电场和磁场对运动电荷的总作用力。高中阶段常用磁场部分 $\mathbf F=q\mathbf v\times\mathbf B$，大小为 $F=qvB\sin\theta$。其中 $q$ 是电荷量，$\mathbf v$ 是速度，$\mathbf B$ 是磁感应强度。磁场力方向总垂直于速度，因此只改变速度方向，不直接改变速率和动能。若电荷垂直进入匀强磁场，洛伦兹力提供向心力，$qvB=mv^2/r$。这个关系常用于分析带电粒子在磁场中的圆周运动、质谱仪和回旋加速器。""",
    "磁通量": r"""磁通量表示磁场穿过某一面积的多少，常用 $\Phi$ 表示。若匀强磁场 $B$ 垂直穿过面积 $S$，则 $\Phi=BS$；一般情况下可写为 $\Phi=BS\cos\theta$，其中 $\theta$ 是磁场方向与面积法线的夹角。磁通量不是磁感应强度本身，而是磁场、面积和方向共同决定的量。它的单位是韦伯。电磁感应中，感应电动势与磁通量变化率有关，$\mathcal E=-\Delta\Phi/\Delta t$。因此判断是否产生感应电流，关键是看闭合回路中的磁通量是否发生变化。""",
    "电磁感应": r"""电磁感应是磁通量变化时在闭合回路中产生感应电流或感应电动势的现象。它说明磁场变化可以激发电效应，是发电机和变压器的基础。法拉第电磁感应定律写为 $\mathcal E=-\Delta\Phi/\Delta t$，其中 $\Phi$ 是穿过回路的磁通量，负号表示感应效果总阻碍磁通量变化。磁通量可以因磁场强弱改变、线圈面积改变或线圈方向改变而变化。若回路闭合，感应电动势会推动感应电流；若不闭合，也仍可存在感应电动势。""",
    "感应电流": r"""感应电流是在闭合回路磁通量发生变化时产生的电流。它的方向由楞次定律判断，大小可由感应电动势和电路电阻估计。若回路电阻为 $R$，感应电动势为 $\mathcal E$，则 $I=\mathcal E/R$；而 $\mathcal E$ 常由 $\mathcal E=-\Delta\Phi/\Delta t$ 给出。这里 $\Phi$ 是磁通量。感应电流不是因为回路中原本有电源，而是变化磁通量在回路中形成了非静电性质的推动作用。只有回路闭合时，电荷才能持续移动形成实际电流。""",
    "感应电动势": r"""感应电动势是磁通量变化时在导体回路中产生的推动电荷运动的作用，常用 $\mathcal E$ 表示。法拉第定律给出 $\mathcal E=-\Delta\Phi/\Delta t$，其中 $\Phi$ 是穿过回路的磁通量，$\Delta\Phi/\Delta t$ 是磁通量变化率。负号体现楞次定律，即感应电动势的方向总使感应电流阻碍原磁通量变化。即使电路没有闭合，也可以有感应电动势，只是没有持续感应电流。导体切割磁感线时常用 $\mathcal E=BLv$，这是磁通量变化公式在特定情形下的结果。""",
    "法拉第电磁感应定律": r"""法拉第电磁感应定律定量描述磁通量变化产生感应电动势的规律。对单匝回路，$\mathcal E=-\Delta\Phi/\Delta t$；对 $N$ 匝线圈，$\mathcal E=-N\Delta\Phi/\Delta t$。其中 $\Phi$ 是每匝磁通量，$N$ 是匝数。磁通量变化越快，感应电动势越大。负号不是大小问题，而是方向问题，表示感应电流的效果反抗磁通量变化。这个定律把“变化的磁场”和“电路中的电压”联系起来，是发电机、变压器和电磁感应实验的共同核心。""",
    "楞次定律": r"""楞次定律用于判断感应电流或感应电动势的方向。它说明，感应电流产生的磁场总要阻碍引起它的磁通量变化。若原磁通量增加，感应磁场倾向于反向抵消增加；若原磁通量减少，感应磁场倾向于同向补偿减少。这个规律体现在法拉第定律的负号中：$\mathcal E=-\Delta\Phi/\Delta t$。楞次定律本质上符合能量守恒，因为若感应电流帮助原变化，就会无中生有地放大能量。判断方向时，先看磁通量如何变，再确定感应磁场方向，最后用右手定则找电流方向。""",
    "自感": r"""自感是一个线圈中电流变化时，它自身磁通量随之变化，从而在本线圈中产生感应电动势的现象。自感电动势总阻碍原电流变化，可写为 $\mathcal E_L=-L\Delta I/\Delta t$，其中 $L$ 是自感系数，$I$ 是线圈电流。电流增大时，自感电动势阻碍增大；电流减小时，它又阻碍减小。线圈储存在磁场中的能量为 $E=\frac12 LI^2$。自感解释了含线圈电路中电流不能突变的原因，也说明开关断开时线圈可能产生较高电压。""",
    "互感": r"""互感是一个线圈中电流变化，引起附近另一个线圈磁通量变化，并在后者中产生感应电动势的现象。若线圈 1 的电流变化率为 $\Delta I_1/\Delta t$，线圈 2 中的感应电动势可写为 $\mathcal E_2=-M\Delta I_1/\Delta t$，其中 $M$ 是互感系数。互感强弱与两线圈距离、相对位置、匝数和铁芯有关。变压器就是利用互感工作的：原线圈交流电流产生变化磁通量，副线圈获得感应电压。互感把一个电路中的变化传递到另一个电路，是电磁耦合的基本形式。""",
    "交变电流": r"""交变电流是大小和方向随时间周期性变化的电流，常见市电就是正弦交流电。理想正弦交流电可写为 $i=I_m\sin\omega t$，其中 $I_m$ 是最大值，$\omega$ 是角频率，$t$ 是时间。交流电的方向会周期性反转，因此不能只用某一瞬间大小描述其热效应。实际用电中常用有效值表示交流电能力，例如正弦电流有效值 $I=I_m/\sqrt2$。交变电流便于通过变压器升降电压，也适合远距离输电。理解它时，要区分瞬时值、最大值和有效值。""",
    "有效值": r"""有效值是用来表示交变电流或交变电压热效应的等效直流值。若某交流电通过同一电阻在一个周期内产生的热量，与某恒定直流电相同，则这个直流值就是交流电的有效值。对正弦电流 $i=I_m\sin\omega t$，有效值为 $I=I_m/\sqrt2$；对正弦电压，$U=U_m/\sqrt2$。这里 $I_m,U_m$ 是最大值。家用电压 220 V 通常指有效值，而不是峰值。有效值让交流电的功率计算仍可使用 $P=UI$ 或 $P=I^2R$ 的熟悉形式。""",
    "变压器": r"""变压器是利用电磁感应改变交流电压的装置，通常由原线圈、副线圈和铁芯组成。原线圈接交流电后产生变化磁通量，副线圈中感应出交流电动势。理想变压器满足 $U_1/U_2=N_1/N_2$，其中 $U_1,U_2$ 是两线圈电压，$N_1,N_2$ 是匝数。匝数多的一侧电压高，匝数少的一侧电压低。若忽略损耗，输入功率近似等于输出功率，$U_1I_1\approx U_2I_2$。变压器只能稳定地用于交流或变化电流，因为恒定直流不能持续产生变化磁通量。""",
    "电磁波": r"""电磁波是变化电场和变化磁场相互激发并在空间传播形成的波。它不需要介质，在真空中传播速度为光速 $c$。电磁波满足 $c=\lambda f$，其中 $\lambda$ 是波长，$f$ 是频率。无线电波、微波、红外线、可见光、紫外线、X 射线都属于电磁波，只是频率和波长不同。电磁波传播时携带能量和动量，电场和磁场方向都与传播方向垂直。高中阶段可把它理解为电磁场扰动向外传播的形式，它把电学、磁学和光学联系起来。""",
    "电磁场": r"""电磁场是电场和磁场统一后的物理场。静止电荷主要表现为电场，电流和运动电荷会产生磁场；当电场或磁场随时间变化时，两者会相互联系。电场对电荷的作用为 $\mathbf F=q\mathbf E$，磁场对运动电荷的作用为 $\mathbf F=q\mathbf v\times\mathbf B$，合起来可写成洛伦兹力形式 $\mathbf F=q(\mathbf E+\mathbf v\times\mathbf B)$。其中 $\mathbf E$ 是电场强度，$\mathbf B$ 是磁感应强度。电磁感应和电磁波说明，电场与磁场不是孤立对象，而是同一电磁相互作用的两个方面。""",
}


